do $$
declare v_coach uuid:=auth.uid();v_athlete uuid;v_block uuid;v_week uuid;v_session uuid;
v_spec jsonb:=$j$[{"n":1,"start":"2026-09-28","end":"2026-10-04","intent":"Calibration week. Arrive at Saturday's 10K ready to race.","sessions":[["WED","easy","Easy · 4 mi","Keep it cheap before the 10K.",4,"8:00/mi or slower.",[{"role":"work","shape":"continuous","distance":4,"distanceUnit":"mi","paceLowSeconds":480}]],["THU","support","Easy + 4 strides","Small mechanical touch, no fitness test.",4,"4 mi easy + 4 × 20 s relaxed strides.",[{"role":"work","shape":"continuous","distance":4,"distanceUnit":"mi","paceLowSeconds":480},{"role":"work","shape":"repetitions","durationSeconds":20,"repeatCount":4,"recoveryKind":"easy","recoverySeconds":60}]],["SAT","key","10K calibration race","First current field read; not a half-pace assignment by itself.",9,"15 min warm-up. Race evenly. Record splits, conditions and feel. 10 min cooldown. No HR cap.",[{"role":"warm_up","shape":"continuous","durationSeconds":900},{"role":"work","shape":"continuous","distance":6.2,"distanceUnit":"mi","rpeLow":9,"rpeHigh":10},{"role":"cool_down","shape":"continuous","durationSeconds":600}]],["SUN","easy","Recovery · 3 mi or off","Move only if it helps recovery.",3,"3 mi very easy or off. Do not make up missed mileage.",[{"role":"work","shape":"continuous","distance":3,"distanceUnit":"mi","paceLowSeconds":480}]]]},{"n":2,"start":"2026-10-05","end":"2026-10-11","intent":"Recover from the 10K, then establish controlled half-marathon pace.","sessions":[["MON","easy","Easy · 4 mi","Reset after the 10K.",4,"8:00/mi or slower.",[{"role":"work","shape":"continuous","distance":4,"distanceUnit":"mi","paceLowSeconds":480}]],["TUE","key","4 × 1 mi · working half pace","Find the band with control. Durability, not threshold.",8,"20 min WU. 4 × 1 mi @ 6:08–6:15/mi, 2 min very easy jog. Open near 6:15. 10 min CD. No HR cap.",[{"role":"warm_up","shape":"continuous","durationSeconds":1200},{"role":"work","shape":"repetitions","distance":1,"distanceUnit":"mi","repeatCount":4,"paceLowSeconds":368,"paceHighSeconds":375,"recoveryKind":"easy","recoverySeconds":120},{"role":"cool_down","shape":"continuous","durationSeconds":600}]],["WED","easy","Easy · 4 mi","Absorb Tuesday.",4,"8:00/mi or slower.",[{"role":"work","shape":"continuous","distance":4,"distanceUnit":"mi","paceLowSeconds":480}]],["THU","support","Easy + 4 strides","The 10K already supplied this week's ceiling stimulus.",4,"4 mi easy + 4 × 20 s relaxed strides.",[{"role":"work","shape":"continuous","distance":4,"distanceUnit":"mi","paceLowSeconds":480},{"role":"work","shape":"repetitions","durationSeconds":20,"repeatCount":4,"recoveryKind":"easy","recoverySeconds":60}]],["SAT","key","Long run · 9 mi","Build time on the legs without another workout.",9,"8:00/mi or slower.",[{"role":"work","shape":"continuous","distance":9,"distanceUnit":"mi","paceLowSeconds":480}]]]},{"n":3,"start":"2026-10-12","end":"2026-10-18","intent":"Extend the hold and reintroduce the second curve.","sessions":[["MON","easy","Easy · 4 mi","Aerobic support.",4,"8:00/mi or slower.",[{"role":"work","shape":"continuous","distance":4,"distanceUnit":"mi","paceLowSeconds":480}]],["TUE","key","3 × 2 mi · working half pace","Longer pieces at the same band. No reward pace.",9,"20 min WU. 3 × 2 mi @ 6:08–6:15/mi, 2 min very easy jog. 10 min CD. Adjust the band first if the 10K says it is too ambitious.",[{"role":"warm_up","shape":"continuous","durationSeconds":1200},{"role":"work","shape":"repetitions","distance":2,"distanceUnit":"mi","repeatCount":3,"paceLowSeconds":368,"paceHighSeconds":375,"recoveryKind":"easy","recoverySeconds":120},{"role":"cool_down","shape":"continuous","durationSeconds":600}]],["WED","easy","Easy · 4 mi","Absorb Tuesday.",4,"8:00/mi or slower.",[{"role":"work","shape":"continuous","distance":4,"distanceUnit":"mi","paceLowSeconds":480}]],["THU","key","Ceiling · 5 × 3 min","Keep speed above half pace alive.",7,"20 min WU. 5 × 3 min @ 5:50–6:00/mi, 2 min very easy jog. Start near 6:00. 10 min CD.",[{"role":"warm_up","shape":"continuous","durationSeconds":1200},{"role":"work","shape":"repetitions","durationSeconds":180,"repeatCount":5,"paceLowSeconds":350,"paceHighSeconds":360,"recoveryKind":"easy","recoverySeconds":120},{"role":"cool_down","shape":"continuous","durationSeconds":600}]],["SAT","key","Long run · 10 mi","Build the chassis. No fast finish.",10,"8:00/mi or slower.",[{"role":"work","shape":"continuous","distance":10,"distanceUnit":"mi","paceLowSeconds":480}]]]},{"n":4,"start":"2026-10-19","end":"2026-10-25","intent":"Largest broken race-pace dose. Ceiling work stays controlled.","sessions":[["MON","easy","Easy · 5 mi","Aerobic support.",5,"8:00/mi or slower.",[{"role":"work","shape":"continuous","distance":5,"distanceUnit":"mi","paceLowSeconds":480}]],["TUE","key","4 × 2 mi · working half pace","Eight miles at the band, broken.",11,"20 min WU. 4 × 2 mi @ 6:08–6:15/mi, 2 min very easy jog. 10 min CD. Do not accelerate because early reps feel cheap.",[{"role":"warm_up","shape":"continuous","durationSeconds":1200},{"role":"work","shape":"repetitions","distance":2,"distanceUnit":"mi","repeatCount":4,"paceLowSeconds":368,"paceHighSeconds":375,"recoveryKind":"easy","recoverySeconds":120},{"role":"cool_down","shape":"continuous","durationSeconds":600}]],["WED","easy","Easy · 4 mi","Absorb Tuesday.",4,"8:00/mi or slower.",[{"role":"work","shape":"continuous","distance":4,"distanceUnit":"mi","paceLowSeconds":480}]],["THU","key","Ceiling · 4 × 4 min","More duration above half pace, not a time trial.",8,"20 min WU. 4 × 4 min @ 5:50–6:00/mi, 2 min very easy jog. 10 min CD.",[{"role":"warm_up","shape":"continuous","durationSeconds":1200},{"role":"work","shape":"repetitions","durationSeconds":240,"repeatCount":4,"paceLowSeconds":350,"paceHighSeconds":360,"recoveryKind":"easy","recoverySeconds":120},{"role":"cool_down","shape":"continuous","durationSeconds":600}]],["SAT","key","Long run · 11 mi","Time on the legs. Leave specific work on Tuesday.",11,"8:00/mi or slower. No fast finish.",[{"role":"work","shape":"continuous","distance":11,"distanceUnit":"mi","paceLowSeconds":480}]]]},{"n":5,"start":"2026-10-26","end":"2026-11-01","intent":"Fresh continuous read. Hold the chosen output without recoveries.","sessions":[["MON","easy","Easy · 4 mi","Arrive fresh enough to read Tuesday.",4,"8:00/mi or slower.",[{"role":"work","shape":"continuous","distance":4,"distanceUnit":"mi","paceLowSeconds":480}]],["TUE","key","6 mi continuous · working half pace","Can the working band remain available continuously?",9,"20 min WU. 6 mi continuous @ 6:08–6:15/mi. Open near 6:15. 10 min CD. Stop at five with control if prior evidence says six is too much.",[{"role":"warm_up","shape":"continuous","durationSeconds":1200},{"role":"work","shape":"continuous","distance":6,"distanceUnit":"mi","paceLowSeconds":368,"paceHighSeconds":375},{"role":"cool_down","shape":"continuous","durationSeconds":600}]],["WED","easy","Easy · 4 mi","Recover from the continuous read.",4,"8:00/mi or slower.",[{"role":"work","shape":"continuous","distance":4,"distanceUnit":"mi","paceLowSeconds":480}]],["THU","key","Ceiling · 4 × 3 min","Keep the ceiling present while reducing dose.",7,"20 min WU. 4 × 3 min @ 5:50–6:00/mi, 2 min very easy jog. 10 min CD.",[{"role":"warm_up","shape":"continuous","durationSeconds":1200},{"role":"work","shape":"repetitions","durationSeconds":180,"repeatCount":4,"paceLowSeconds":350,"paceHighSeconds":360,"recoveryKind":"easy","recoverySeconds":120},{"role":"cool_down","shape":"continuous","durationSeconds":600}]],["SAT","key","Long run · 12 mi","Last substantial chassis day. Keep it easy.",12,"8:00/mi or slower. No race-pace finish.",[{"role":"work","shape":"continuous","distance":12,"distanceUnit":"mi","paceLowSeconds":480}]]]},{"n":6,"start":"2026-11-02","end":"2026-11-08","intent":"Reduce load while keeping both rhythms familiar.","sessions":[["MON","easy","Easy · 4 mi","Start taper without going flat.",4,"8:00/mi or slower.",[{"role":"work","shape":"continuous","distance":4,"distanceUnit":"mi","paceLowSeconds":480}]],["TUE","key","3 × 1 mi · half rhythm","Familiar pace, short exposure, finish wanting more.",7,"15 min WU. 3 × 1 mi @ 6:05–6:12/mi, 2 min very easy jog. 10 min CD. Rhythm, not a new test.",[{"role":"warm_up","shape":"continuous","durationSeconds":900},{"role":"work","shape":"repetitions","distance":1,"distanceUnit":"mi","repeatCount":3,"paceLowSeconds":365,"paceHighSeconds":372,"recoveryKind":"easy","recoverySeconds":120},{"role":"cool_down","shape":"continuous","durationSeconds":600}]],["WED","easy","Easy · 3 mi","Recovery.",3,"Easy enough to forget pace.",[{"role":"work","shape":"continuous","distance":3,"distanceUnit":"mi","paceLowSeconds":480}]],["THU","support","Ceiling touch · 4 × 2 min","Small reminder of speed without carrying fatigue.",5,"15 min WU. 4 × 2 min @ 5:50–6:00/mi, 2 min very easy jog. 10 min CD.",[{"role":"warm_up","shape":"continuous","durationSeconds":900},{"role":"work","shape":"repetitions","durationSeconds":120,"repeatCount":4,"paceLowSeconds":350,"paceHighSeconds":360,"recoveryKind":"easy","recoverySeconds":120},{"role":"cool_down","shape":"continuous","durationSeconds":600}]],["SAT","easy","Easy · 7 mi + strides","Stay loose. Do not prove anything.",7,"7 mi easy + 4 × 20 s relaxed strides if good.",[{"role":"work","shape":"continuous","distance":7,"distanceUnit":"mi","paceLowSeconds":480},{"role":"work","shape":"repetitions","durationSeconds":20,"repeatCount":4,"recoveryKind":"easy","recoverySeconds":60}]]]},{"n":7,"start":"2026-11-09","end":"2026-11-15","intent":"Race week. Final race line comes from the 10K, continuous read, and taper.","sessions":[["MON","easy","Easy · 3 mi + strides","Stay loose.",3,"3 mi easy + 4 × 20 s relaxed strides.",[{"role":"work","shape":"continuous","distance":3,"distanceUnit":"mi","paceLowSeconds":480},{"role":"work","shape":"repetitions","durationSeconds":20,"repeatCount":4,"recoveryKind":"easy","recoverySeconds":60}]],["TUE","easy","Shakeout · 2 mi","Short and calm.",2,"2 mi easy. No workout.",[{"role":"work","shape":"continuous","distance":2,"distanceUnit":"mi","paceLowSeconds":480}]],["WED","key","Race · Half Marathon","Race the fitness brought to the line. Sub-1:20 is the goal, not a guaranteed opening split.",13.1,"15 min WU. Final opening pace is set after the Oct 3 10K and Oct 27 continuous read. Start controlled. No HR cap.",[{"role":"warm_up","shape":"continuous","durationSeconds":900},{"role":"work","shape":"continuous","distance":13.1,"distanceUnit":"mi","rpeLow":9,"rpeHigh":10}]]]}]$j$::jsonb;w jsonb;s jsonb;wo bigint;so bigint;
begin
if exists(select 1 from public.athletes where slug='elijah') then raise exception 'Elijah already exists'; end if;
insert into public.athletes(slug,display_name,first_name,home_surface,target_event,goal_label,program_name,account_label,active,goal_seconds,goal_pace_seconds,delivery,attention_position)
values('elijah','Elijah','Elijah','form','Half marathon · Nov 11, 2026','Sub-1:20 · aggressive','Ceiling × Durability','Coached Athlete',true,4800,366,'app',8) returning id into v_athlete;
insert into public.athlete_memberships values(v_athlete,v_coach,'coach','active',now());
insert into public.training_blocks(athlete_id,source,name,block_number,target_event,goal_label,current_week,total_weeks,starts_on,ends_on,status,authored_by,race_on,goal_statement,week_starts_on,purpose,race_name,race_place)
values(v_athlete,'coach_authored','Ceiling × Durability · Nov 11',1,'Half marathon · Nov 11, 2026','Sub-1:20 · aggressive',1,7,date '2026-09-28',date '2026-11-15','active',v_coach,date '2026-11-11','Prepare an aggressive sub-1:20 attempt without treating it as a prediction. Oct 3 10K calibrates the band; Oct 27 checks the continuous hold. Preserve the ceiling while developing durability.',1,'development','Half Marathon',null) returning id into v_block;
insert into public.block_pace_bands(block_id,athlete_id,position,label,value,low_seconds,high_seconds,when_line,authored_by) values
(v_block,v_athlete,1,'EASY','8:00 /mi or slower',480,null,'A speed ceiling, not a target. Shorten easy mileage rather than forcing a quota.',v_coach),
(v_block,v_athlete,2,'WORKING HALF PACE','6:08–6:15 /mi',368,375,'Provisional until the Oct 3 10K is reviewed. Sub-1:20 goal pace is about 6:06/mi; the goal is not evidence.',v_coach),
(v_block,v_athlete,3,'CEILING REFERENCE','5:50–6:00 /mi',350,360,'Provisional around the athlete-reported 18:20 5K. Short Thursday work only. No HR cap.',v_coach);
for w,wo in select value,ordinality from jsonb_array_elements(v_spec) with ordinality loop
 insert into public.training_weeks(athlete_id,block_id,week_number,starts_on,ends_on,intent,matters_because,state,authored_by)
 values(v_athlete,v_block,(w->>'n')::int,(w->>'start')::date,(w->>'end')::date,w->>'intent',
 case when (w->>'n')::int=1 then 'The 10K gives a current read before the half-specific progression.' when (w->>'n')::int=7 then 'The race is the expression; no more fitness is built this week.' else 'Advance the hold while protecting recovery and the second curve.' end,'planned',v_coach) returning id into v_week;
 for s,so in select value,ordinality from jsonb_array_elements(w->'sessions') with ordinality loop
  v_session:=public.author_session(v_athlete,v_week,s->>0,s->>2,s->>3,(w->>'start')::date+case s->>0 when 'MON' then 0 when 'TUE' then 1 when 'WED' then 2 when 'THU' then 3 when 'FRI' then 4 when 'SAT' then 5 else 6 end,so::smallint,(s->>4)::numeric,'mi',null,null,null,s->6,s->>5);
  update public.planned_sessions set role=s->>1,is_key=(s->>1='key') where id=v_session;
 end loop;
end loop;
if (select count(*) from public.training_weeks where athlete_id=v_athlete and block_id=v_block)<>7 then raise exception 'expected 7 weeks';end if;
if (select count(*) from public.planned_sessions where athlete_id=v_athlete)<>32 then raise exception 'expected 32 sessions';end if;
end $$;